<?php use App\Core\Env; use App\Core\View; $baseUrl=rtrim((string)Env::get('APP_URL',''),'/'); ?>
<div class="client-detail-heading"><a href="<?= $baseUrl ?>/incidents" class="back-link"><i data-lucide="arrow-left"></i> Retour aux incidents</a><div class="detail-main"><div class="incident-detail-icon"><i data-lucide="triangle-alert"></i></div><div><div class="detail-title-line"><h1><?= htmlspecialchars($incident['incident_reference'],ENT_QUOTES,'UTF-8') ?></h1><?= View::partial('components/status-badge',['status'=>$incident['status']]) ?><span class="incident-type-badge"><?= htmlspecialchars(mb_convert_case($incident['incident_type'],MB_CASE_TITLE,'UTF-8'),ENT_QUOTES,'UTF-8') ?></span></div><p><?= htmlspecialchars(($incident['delivery_reference']?:'Sans livraison').' · '.($incident['company_name']?:$incident['driver_name']),ENT_QUOTES,'UTF-8') ?></p></div></div></div>
<section class="incident-detail-grid"><article class="panel incident-primary"><div class="detail-card-head"><h2>Signalement</h2><i data-lucide="file-warning"></i></div><p class="incident-description"><?= nl2br(htmlspecialchars($incident['description'],ENT_QUOTES,'UTF-8')) ?></p><dl><div><dt>Date et heure</dt><dd><?= date('d/m/Y à H:i:s',strtotime($incident['occurred_at'])) ?></dd></div><div><dt>Chauffeur</dt><dd><?= htmlspecialchars($incident['driver_name'],ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Véhicule</dt><dd><?= htmlspecialchars($incident['registration_number']?:'Non renseigné',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>GPS</dt><dd><?= $incident['latitude']?htmlspecialchars($incident['latitude'].', '.$incident['longitude'].' (±'.$incident['accuracy_m'].' m)',ENT_QUOTES,'UTF-8'):'Non capturé' ?></dd></div><div><dt>Signalé par</dt><dd><?= htmlspecialchars($incident['reporter_name']?:'Système',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Gravité</dt><dd><?= htmlspecialchars($incident['severity'],ENT_QUOTES,'UTF-8') ?></dd></div></dl></article><article class="panel incident-delivery-card"><div class="detail-card-head"><h2>Livraison concernée</h2><i data-lucide="package-search"></i></div><?php if($incident['delivery_id']): ?><a href="<?= $baseUrl ?>/deliveries/<?= (int)$incident['delivery_id'] ?>"><strong><?= htmlspecialchars($incident['delivery_reference'],ENT_QUOTES,'UTF-8') ?></strong><span><?= htmlspecialchars($incident['company_name'],ENT_QUOTES,'UTF-8') ?></span><small><?= htmlspecialchars($incident['site_name'].' · '.$incident['site_address'].', '.$incident['site_city'],ENT_QUOTES,'UTF-8') ?></small><i data-lucide="arrow-up-right"></i></a><?php else: ?><p>Ancien incident sans livraison associée.</p><?php endif; ?></article></section>
<?php if($incident['photos']): ?><section class="panel incident-photo-panel"><div class="panel-head"><div><h2>Photos de l’incident</h2><p><?= count($incident['photos']) ?> pièce(s) jointe(s) sécurisée(s)</p></div></div><div class="incident-photo-grid"><?php foreach($incident['photos'] as $photo): ?><a href="<?= $baseUrl ?>/incidents/<?= (int)$incident['id'] ?>/photos/<?= (int)$photo['id'] ?>" target="_blank"><img src="<?= $baseUrl ?>/incidents/<?= (int)$incident['id'] ?>/photos/<?= (int)$photo['id'] ?>" alt="Photo de l’incident"><span><i data-lucide="maximize-2"></i></span></a><?php endforeach; ?></div></section><?php endif; ?>
<section class="incident-treatment-grid"><article class="panel"><div class="panel-head"><div><h2>Prise en charge</h2><p>Affectation et action corrective prévue</p></div></div><?php if($incident['status']==='Résolu'): ?><dl class="resolution-summary"><div><dt>Responsable</dt><dd><?= htmlspecialchars($incident['responsible_name']?:'Non affecté',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Action corrective</dt><dd><?= nl2br(htmlspecialchars($incident['corrective_action']?:'Non renseignée',ENT_QUOTES,'UTF-8')) ?></dd></div></dl><?php elseif($canManage): ?><form id="incidentUpdateForm" data-incident-id="<?= (int)$incident['id'] ?>"><label class="field"><span>Responsable</span><select name="responsible_user_id"><option value="">Non affecté</option><?php foreach($users as $user): ?><option value="<?= (int)$user['id'] ?>" <?= (int)$incident['responsible_user_id']===(int)$user['id']?'selected':'' ?>><?= htmlspecialchars($user['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label><label class="field"><span>Statut</span><select name="status"><option <?= $incident['status']==='Ouvert'?'selected':'' ?>>Ouvert</option><option <?= $incident['status']==='En traitement'?'selected':'' ?>>En traitement</option></select></label><label class="field"><span>Action corrective</span><textarea name="corrective_action" rows="5" placeholder="Mesures prises ou à engager"><?= htmlspecialchars($incident['corrective_action']??'',ENT_QUOTES,'UTF-8') ?></textarea></label><button class="button button-primary" type="submit"><i data-lucide="save"></i> Enregistrer le traitement</button></form><?php else: ?><p>Traitement réservé aux responsables autorisés.</p><?php endif; ?></article><article class="panel resolution-card <?= $incident['status']==='Résolu'?'resolved':'' ?>"><div class="panel-head"><div><h2>Résolution</h2><p>Clôture de l’événement et reprise du workflow</p></div><i data-lucide="<?= $incident['status']==='Résolu'?'shield-check':'circle-dashed' ?>"></i></div><?php if($incident['status']==='Résolu'): ?><div class="resolved-stamp"><i data-lucide="check"></i><span>Résolu le <?= date('d/m/Y à H:i',strtotime($incident['resolved_at'])) ?><small>par <?= htmlspecialchars($incident['resolver_name']?:'Système',ENT_QUOTES,'UTF-8') ?></small></span></div><blockquote><?= nl2br(htmlspecialchars($incident['resolution'],ENT_QUOTES,'UTF-8')) ?></blockquote><?php elseif($canResolve): ?><form id="incidentResolveForm" data-incident-id="<?= (int)$incident['id'] ?>"><label class="field"><span>Action corrective appliquée *</span><textarea name="corrective_action" rows="4" required><?= htmlspecialchars($incident['corrective_action']??'',ENT_QUOTES,'UTF-8') ?></textarea></label><label class="field"><span>Résolution *</span><textarea name="resolution" rows="5" placeholder="Décrivez le résultat et les vérifications effectuées" required></textarea></label><button class="button button-success" type="submit"><i data-lucide="shield-check"></i> Marquer comme résolu</button></form><?php else: ?><p>Vous ne disposez pas de la permission de résolution.</p><?php endif; ?></article></section>
